// Existing archive folders take priority over names generated by the app.
export const facilityFolderMap = {
  'Brooklyn': 'Brooklyn Center',
  'Bronx': 'Bronx Center',
  'Corning': 'Corning Center',
  'Essex': 'Essex Center',
  'Washington': 'Washington Center',
  'N Riverview': 'Northern Riverview'
};

export function preferredFacilityFolder(name) {
  const key = String(name || '').trim().toLowerCase();
  return Object.entries(facilityFolderMap).find(([alias, folder]) =>
    alias.toLowerCase() === key || folder.toLowerCase() === key)?.[1] || '';
}
